package com.bank.migrate.store;

import com.bank.migrate.model.AccountRow;
import java.util.*;

// Simulates a large accounts table.
public class TableSim {
    private final List<AccountRow> rows = new ArrayList<>();
    public TableSim(int n) { for (long i = 1; i <= n; i++) rows.add(new AccountRow(i, i * 10000)); }
    public List<AccountRow> all() { return rows; }
    public long countNullDecimal() { return rows.stream().filter(r -> r.balanceDecimal == null).count(); }
}
