package com.bank.migrate.service;

import com.bank.migrate.model.AccountRow;
import java.math.BigDecimal;
import java.math.RoundingMode;

// Step 2: writes BOTH the old and the new column on every change.
public class DualWriteAccountService {
    public void updateBalance(AccountRow row, long newPaise) {
        row.balancePaise = newPaise;                                   // old
        row.balanceDecimal = BigDecimal.valueOf(newPaise)
                .divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_UP); // new, kept in sync
    }
}
