package com.bank.migrate.service;

import com.bank.migrate.model.AccountRow;
import com.bank.migrate.store.TableSim;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.List;
import java.util.logging.Logger;

// Step 3: fill historical rows in SMALL batches, short transactions, throttled.
public class Backfiller {
    private static final Logger log = Logger.getLogger(Backfiller.class.getName());
    private final TableSim table;
    public Backfiller(TableSim table) { this.table = table; }

    public void backfillInBatches(int batchSize) {
        List<AccountRow> all = table.all();
        int done = 0;
        for (int i = 0; i < all.size(); i += batchSize) {
            int end = Math.min(i + batchSize, all.size());
            for (int j = i; j < end; j++) {                 // one short "transaction" per batch
                AccountRow r = all.get(j);
                if (r.balanceDecimal == null) {
                    r.balanceDecimal = BigDecimal.valueOf(r.balancePaise)
                            .divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_UP);
                }
            }
            done = end;
            throttle();                                     // pause to protect replication/IO
            final int d = done;
            log.info(() -> "Backfilled up to row " + d);
        }
    }
    private void throttle() { try { Thread.sleep(5); } catch (InterruptedException ignored) {} }
}
