package com.bank.migrate;

import com.bank.migrate.model.AccountRow;
import com.bank.migrate.service.Backfiller;
import com.bank.migrate.service.DualWriteAccountService;
import com.bank.migrate.store.TableSim;

public class MigrationApplication {
    public static void main(String[] args) {
        TableSim table = new TableSim(1000); // pretend 400M in production

        // Step 1 Expand: nullable column added (simulated by the AccountRow field being null).
        System.out.println("After expand, null decimal rows = " + table.countNullDecimal());

        // Step 2 Dual-write: new/updated rows populate BOTH columns.
        DualWriteAccountService svc = new DualWriteAccountService();
        svc.updateBalance(table.all().get(0), 55000); // a live update during migration
        System.out.println("Row 1 after dual-write: decimal=" + table.all().get(0).balanceDecimal);

        // Step 3 Backfill historical rows in batches.
        new Backfiller(table).backfillInBatches(100);
        System.out.println("After backfill, null decimal rows = " + table.countNullDecimal());

        // Step 4 Switch reads + add NOT NULL safely (all rows now populated).
        // Step 5 Contract: drop old column later (simulated — we stop using balancePaise).
        System.out.println("Ready to switch reads to balance_decimal, then drop balance_paise.");
    }
}
